#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <errno.h>
int main(int argc, char** argv) {
 if(argc!=2)return 1;
 int out=open(argv[1],O_WRONLY|O_CREAT|O_EXCL,0600);if(out<0)return 2;
 if(ftruncate(out,1048576)||pwrite(out,"x",1,65536)!=1||fsync(out)||close(out))return 3;
 int fd=open(argv[1],O_EVTONLY|O_CLOEXEC|O_NOFOLLOW);if(fd<0)return 4;
 errno=0;long long data=(long long)lseek(fd,0,SEEK_DATA);int data_error=errno;
 errno=0;long long hole=(long long)lseek(fd,data>=0?data:0,SEEK_HOLE);int hole_error=errno;
 printf("{\"event_only_data\":%lld,\"data_errno\":%d,\"event_only_hole\":%lld,\"hole_errno\":%d}\n",data,data_error,hole,hole_error);
 if(close(fd)||unlink(argv[1]))return 5;return 0;
}
